// "¿Hará calor en septiembre?" — temperature chart (inline SVG, no libraries).
// Data and statistics come from clima.js, generated by scripts/clima.py.
import { clima } from './clima.js';

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const TXT = {
  es: {
    title: 'Temperaturas del 15 al 21 de septiembre en Villanueva de la Serena',
    lead: (mx, mn) => `Para el sábado 18 de septiembre de 2027 la tendencia apunta a una máxima de unos ${mx.fit} °C por la tarde (lo más probable, entre ${mx.pi[0]} y ${mx.pi[1]} °C) y a una mínima de unos ${mn.fit} °C de madrugada (entre ${mn.pi[0]} y ${mn.pi[1]} °C).`,
    past: (mx, mn, n) => `En los últimos ${n} años, esa semana la máxima media fue de ${mx.overall} °C (con días de ${mx.lowest} a ${mx.highest} °C) y la mínima media de ${mn.overall} °C.`,
    max: 'Máxima (tarde)',
    min: 'Mínima (noche)',
    day: 'Cada día',
    mean: 'Media de la semana',
    trend: 'Tendencia',
    ci: 'IC 95 % de la media esperada',
    pi: 'Intervalo de predicción 95 % para ese día',
    forecast: 'previsión',
    caption: (mx, mn, acc) => `Puntos pequeños: cada día entre el 15 y el 21 de septiembre; puntos grandes: media de esa semana. Línea discontinua: tendencia lineal de las medias anuales (máxima ${sign(mx.trend.slopePerDecade)} °C por década, IC 95 % ${mx.trend.slopeCI95PerDecade[0]} a ${mx.trend.slopeCI95PerDecade[1]}; mínima ${sign(mn.trend.slopePerDecade)} °C, IC 95 % ${mn.trend.slopeCI95PerDecade[0]} a ${mn.trend.slopeCI95PerDecade[1]}). Con solo diez años la tendencia no es significativa, por eso las bandas de 2027 son anchas. Es una estimación estadística, no una previsión meteorológica. Datos: reanálisis ERA5 de Copernicus vía Open-Meteo (CC BY 4.0), punto de rejilla a 1,6 km del restaurante, consultado el ${acc}. El reanálisis suaviza los extremos; un termómetro de calle puede marcar algo más por la tarde.`,
    dataTitle: 'Ver los datos',
    year: 'Año',
    meanMax: 'Máxima media',
    meanMin: 'Mínima media',
    d18Max: 'Máxima el 18',
    d18Min: 'Mínima el 18',
  },
  en: {
    title: 'Temperatures from 15 to 21 September in Villanueva de la Serena',
    lead: (mx, mn) => `For Saturday 18 September 2027 the trend points to a high of about ${mx.fit} °C in the afternoon (most likely between ${mx.pi[0]} and ${mx.pi[1]} °C) and a low of about ${mn.fit} °C before dawn (between ${mn.pi[0]} and ${mn.pi[1]} °C).`,
    past: (mx, mn, n) => `Over the last ${n} years, that week’s average high was ${mx.overall} °C (days ranged from ${mx.lowest} to ${mx.highest} °C) and the average low ${mn.overall} °C.`,
    max: 'High (afternoon)',
    min: 'Low (night)',
    day: 'Each day',
    mean: 'Weekly mean',
    trend: 'Trend',
    ci: '95% CI of the expected mean',
    pi: '95% prediction interval for that day',
    forecast: 'forecast',
    caption: (mx, mn, acc) => `Small dots: each day from 15 to 21 September; large dots: that week’s mean. Dashed line: linear trend of the yearly means (high ${sign(mx.trend.slopePerDecade)} °C per decade, 95% CI ${mx.trend.slopeCI95PerDecade[0]} to ${mx.trend.slopeCI95PerDecade[1]}; low ${sign(mn.trend.slopePerDecade)} °C, 95% CI ${mn.trend.slopeCI95PerDecade[0]} to ${mn.trend.slopeCI95PerDecade[1]}). With only ten years the trend is not significant, which is why the 2027 bands are wide. This is a statistical estimate, not a weather forecast. Data: Copernicus ERA5 reanalysis via Open-Meteo (CC BY 4.0), grid point 1.6 km from the venue, accessed ${acc}. Reanalysis smooths extremes; a street thermometer may read a little higher in the afternoon.`,
    dataTitle: 'Show the data',
    year: 'Year',
    meanMax: 'Mean high',
    meanMin: 'Mean low',
    d18Max: 'High on the 18th',
    d18Min: 'Low on the 18th',
  },
};

function sign(v) { return (/^[-−]/.test(String(v)) ? '' : '+') + v; }

// Spanish uses a decimal comma; applied to every number in the strings.
function localise(lang, value) {
  if (lang !== 'es') return typeof value === 'number' ? value.toFixed(1) : Array.isArray(value) ? value.map((v) => localise(lang, v)) : value && typeof value === 'object' ? Object.fromEntries(Object.entries(value).map(([k, v]) => [k, localise(lang, v)])) : value;
  if (typeof value === 'number') return value.toFixed(1).replace('.', ',').replace('-', '−');
  if (Array.isArray(value)) return value.map((v) => localise(lang, v));
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, localise(lang, v)]));
  return value;
}

export function climateFigure(lang) {
  const L = TXT[lang] || TXT.es;
  const d = clima;
  const n = d.years.length;
  const mx = localise(lang, d.max);
  const mn = localise(lang, d.min);
  const acc = new Date(d.accessed + 'T12:00:00Z').toLocaleDateString(lang === 'en' ? 'en-GB' : 'es-ES', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });

  // geometry (viewBox units)
  const W = 480, H = 300, l = 34, r = 10, top = 12, bottom = 30;
  const yMin = 10, yMax = 42;
  const slots = n + 1.6; // ten years, a gap, 2027
  const step = (W - l - r) / slots;
  const xOf = (i) => l + step * (i + 0.5) + (i >= n ? step * 0.6 : 0);
  const yOf = (v) => top + (yMax - v) / (yMax - yMin) * (H - top - bottom);
  const f = (v) => v.toFixed(1);

  const grid = [];
  for (let v = 10; v <= 40; v += 5) {
    grid.push(`<line x1="${l}" x2="${W - r}" y1="${f(yOf(v))}" y2="${f(yOf(v))}" class="clima__grid"/>`
      + `<text x="${l - 6}" y="${f(yOf(v) + 4)}" class="clima__tick" text-anchor="end">${v}°</text>`);
  }
  const xlab = d.years.map((y, i) => `<text x="${f(xOf(i))}" y="${H - 10}" class="clima__tick" text-anchor="middle">’${String(y).slice(2)}</text>`).join('')
    + `<text x="${f(xOf(n))}" y="${H - 10}" class="clima__tick clima__tick--target" text-anchor="middle">${d.target}</text>`;

  const series = (key) => {
    const s = d[key];
    const days = s.days.map((row, i) => row.map((v, j) => `<circle cx="${f(xOf(i) + (j - 3) * 1.6)}" cy="${f(yOf(v))}" r="2.2" class="clima__day"/>`).join('')).join('');
    const means = s.mean.map((v, i) => `<circle cx="${f(xOf(i))}" cy="${f(yOf(v))}" r="4.2" class="clima__mean"/>`).join('');
    const tr = (y) => s.trend.intercept + s.trend.slope * y;
    const fc = s.forecast, w = step * 0.5, x = xOf(n) + (key === 'max' ? 0.28 : -0.28) * step;
    const trend = `<line x1="${f(xOf(0))}" y1="${f(yOf(tr(d.years[0])))}" x2="${f(x)}" y2="${f(yOf(tr(d.target)))}" class="clima__trend"/>`;
    const band = `<rect x="${f(x - w / 2)}" width="${f(w)}" y="${f(yOf(fc.pi[1]))}" height="${f(yOf(fc.pi[0]) - yOf(fc.pi[1]))}" class="clima__pi"/>`
      + `<rect x="${f(x - w / 2)}" width="${f(w)}" y="${f(yOf(fc.ci[1]))}" height="${f(yOf(fc.ci[0]) - yOf(fc.ci[1]))}" class="clima__ci"/>`
      + `<circle cx="${f(x)}" cy="${f(yOf(fc.fit))}" r="5" class="clima__fit"/>`;
    return `<g class="clima__s clima__s--${key}">${band}${trend}${days}${means}</g>`;
  };

  const svg = `
      <svg class="clima__svg" viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="clima-t clima-d" focusable="false">
        <title id="clima-t">${esc(L.title)}</title>
        <desc id="clima-d">${esc(L.past(mx, mn, n) + ' ' + L.lead(mx.forecast, mn.forecast))}</desc>
        ${grid.join('')}
        ${series('min')}${series('max')}
        ${xlab}
      </svg>`;

  const key = (cls, label) => `<li><span class="clima__key ${cls}" aria-hidden="true"></span>${esc(label)}</li>`;
  const rows = d.years.map((y, i) => `<tr><th scope="row">${y}</th><td>${localise(lang, d.max.mean[i])}</td><td>${localise(lang, d.min.mean[i])}</td><td>${localise(lang, d.max.day18[i])}</td><td>${localise(lang, d.min.day18[i])}</td></tr>`).join('');

  return `
    <figure class="clima" lang="${lang}">
      <p class="clima__lead">${esc(L.past(mx, mn, n))} <strong>${esc(L.lead(mx.forecast, mn.forecast))}</strong></p>
      ${svg}
      <ul class="clima__legend">
        ${key('clima__key--max', L.max)}${key('clima__key--min', L.min)}
        ${key('clima__key--day', L.day)}${key('clima__key--mean', L.mean)}${key('clima__key--trend', L.trend)}
        ${key('clima__key--ci', L.ci)}${key('clima__key--pi', L.pi)}
      </ul>
      <figcaption class="clima__cap">${esc(L.caption(mx, mn, acc))}</figcaption>
      <details class="clima__data">
        <summary>${esc(L.dataTitle)}</summary>
        <table>
          <thead><tr><th scope="col">${esc(L.year)}</th><th scope="col">${esc(L.meanMax)}</th><th scope="col">${esc(L.meanMin)}</th><th scope="col">${esc(L.d18Max)}</th><th scope="col">${esc(L.d18Min)}</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </details>
    </figure>`;
}
